// LocalServiceHandler is an implementation of the raptor.wings.local.v1.LocalService service.
type LocalServiceHandler interface {
	// GetStatus reports node health.
	GetStatus(context.Context, *v1.GetStatusRequest) (*v1.GetStatusResponse, error)
	// ShutdownServers gracefully stops every running server with its egg's
	// stop command, without changing whether it should run, so servers start
	// again when the host is back. Called by raptor-shutdown.service when the
	// host shuts down. Root only.
	ShutdownServers(context.Context, *v1.ShutdownServersRequest) (*v1.ShutdownServersResponse, error)
	// ListServers lists every server with its state and resource usage. It
	// takes about half a second (CPU usage is measured over an interval).
	ListServers(context.Context, *v1.ListServersRequest) (*v1.ListServersResponse, error)
	// Power starts, stops, restarts, or kills a server and returns when it's
	// done (a stop can take up to the server's stop timeout). Root only.
	Power(context.Context, *v1.PowerRequest) (*v1.PowerResponse, error)
	// StreamConsole sends the console history and then live console output
	// until the client disconnects or the server is deleted.
	StreamConsole(context.Context, *v1.StreamConsoleRequest, *connect.ServerStream[v1.StreamConsoleResponse]) error
	// SendCommand writes a command to a running server's console. Root only.
	SendCommand(context.Context, *v1.SendCommandRequest) (*v1.SendCommandResponse, error)
	// TailLogs sends a server's output from Docker's log store, which goes
	// back further than the console history, optionally following it.
	TailLogs(context.Context, *v1.TailLogsRequest, *connect.ServerStream[v1.TailLogsResponse]) error
	// ListBackups lists a server's backups, newest first, or every backup on
	// the node (including offsite backups of deleted servers).
	ListBackups(context.Context, *v1.ListBackupsRequest) (*v1.ListBackupsResponse, error)
	// CreateBackup backs up a server to its destination. Root only.
	CreateBackup(context.Context, *v1.CreateBackupRequest) (*v1.CreateBackupResponse, error)
	// RestoreBackup replaces a server's files with one of its backups, after
	// taking a safety backup of the current files. The server is stopped
	// meanwhile and started again if it was meant to be running. Root only.
	RestoreBackup(context.Context, *v1.RestoreBackupRequest) (*v1.RestoreBackupResponse, error)
	// Update installs another Wings version: the one asked for, else the
	// pinned one, else the newest in the node's channel. Wings downloads and
	// verifies it, then restarts to run it on trial (servers keep running); if
	// it isn't healthy within 5 minutes, Wings rolls back. The reply comes
	// before the restart: GetStatus reports how the update went. Checking is
	// open to the raptor group; installing is root only.
	Update(context.Context, *v1.UpdateRequest) (*v1.UpdateResponse, error)
	// ListKeys lists the passkeys this node trusts for signed actions, and
	// delegations.
	ListKeys(context.Context, *v1.ListKeysRequest) (*v1.ListKeysResponse, error)
	// ListAudit lists signed dangerous actions (run or rejected) and key
	// resets, newest first, from the node's own records.
	ListAudit(context.Context, *v1.ListAuditRequest) (*v1.ListAuditResponse, error)
	// StartKeyReset begins re-pairing the node's owner passkey: it returns a
	// one-time code for the owner to enter in the Panel. Nothing changes until
	// ConfirmKeyReset. Root only.
	StartKeyReset(context.Context, *v1.StartKeyResetRequest) (*v1.StartKeyResetResponse, error)
	// GetKeyReset reports a key reset's state: waiting for the Panel, or a
	// key waiting for root to confirm its fingerprint. Root only.
	GetKeyReset(context.Context, *v1.GetKeyResetRequest) (*v1.GetKeyResetResponse, error)
	// ConfirmKeyReset pins the key that paired as the node's only owner key,
	// removing every other trusted key and delegation. Root only.
	ConfirmKeyReset(context.Context, *v1.ConfirmKeyResetRequest) (*v1.ConfirmKeyResetResponse, error)
	// CancelKeyReset ends a key reset without changing any key. Root only.
	CancelKeyReset(context.Context, *v1.CancelKeyResetRequest) (*v1.CancelKeyResetResponse, error)
	// PinOwnerKey trusts the owner passkey the Panel handed over at enrollment
	// (raptor link, raptor bootstrap), after checking its signature and that
	// it names the join token used. Only while the node trusts no owner key.
	// Root only.
	PinOwnerKey(context.Context, *v1.PinOwnerKeyRequest) (*v1.PinOwnerKeyResponse, error)
	// TestNotifications sends a test message to every notification target in
	// config.yml and reports how each went. Root only.
	TestNotifications(context.Context, *v1.TestNotificationsRequest) (*v1.TestNotificationsResponse, error)
	// ImportServer creates a server from another panel's (raptor import):
	// its configuration, and a copy of its directory. The original is left
	// as it was. Root only.
	ImportServer(context.Context, *v1.ImportServerRequest) (*v1.ImportServerResponse, error)
	// GetMetrics returns a server's resource history and its latest sample.
	GetMetrics(context.Context, *v1.GetMetricsRequest) (*v1.GetMetricsResponse, error)
}

